<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use MarketForecast\Reports\EmailDeliveryService;use PHPUnit\Framework\TestCase;use RuntimeException;
final class EmailDeliveryTest extends TestCase { public function testUnconfiguredMailerDoesNotSend():void{$r=(new EmailDeliveryService())->send(['report_date'=>'2026-01-01','health'=>[],'reliability'=>[],'title'=>'Daily','experiment'=>'EXP-001'],'user@example.com');self::assertSame('NOT_SENT',$r['status']);} public function testTransportReceivesHtmlAndText():void{$called=null;$s=new EmailDeliveryService(function(...$args)use(&$called){$called=$args;return ['status'=>'SENT'];});self::assertSame('SENT',$s->send(['report_date'=>'2026-01-01','health'=>[],'reliability'=>[],'title'=>'Daily','experiment'=>'EXP-001'],'user@example.com')['status']);self::assertSame('user@example.com',$called[0]);self::assertStringContainsString('<html',$called[2]);self::assertStringContainsString('FRF 2.0',$called[3]);self::assertSame(1,substr_count($called[2],'https://rayanhost.org/AlpacaAIApp/public/reports.php'));} public function testMissingRecipientFailsClosed():void{$this->expectException(RuntimeException::class);(new EmailDeliveryService())->send(['report_date'=>'2026-01-01'],'');} }
